INSERT INTO `v1_a1a39b00b7b4667e3dbce2650ac85db980828b1ff4c85650994a8ed3d079bbcb` VALUES (1, "剛力なる鳥像", 101, 1, 0, "ガーゴイル", 0, "高い物理攻撃力を宿し、強力な範囲攻撃を行うよう\nプログラムされたボスが現れる。");
